import { FormEvent, useCallback, useEffect, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { Button } from './components/ui/button';
import { Input } from './components/ui/input';
import { Link, Navigate, Route, Routes, useLocation, useParams, useSearchParams, Outlet } from 'react-router-dom';
import { Activity, ArrowDownRight, ArrowLeft, ArrowRight, Bell, BookOpen, CalendarDays, Check, ChevronDown, ChevronRight, CircleHelp, ClipboardList, Clock3, DoorOpen, GraduationCap, LayoutDashboard, LifeBuoy, LogOut, Menu, MessageSquare, Moon, MoreHorizontal, Plus, Search, Settings, ShieldCheck, Sparkles, Sun, Users, X } from 'lucide-react';
import { api, dateLabel, initials, roleName, type Row, type Session } from './lib/api';

import { PasswordResetPage, ResetRequest } from './account-email';
import { ClassAttendance, ClassDocuments, ClassExams, ClassRosterImport } from './class-tools';
import { AssignmentPage, assignmentLink } from './assignment';
import { AgendaCalendar, calendarQuery, courseColor, defaultSubjectColor } from './agenda';

type Notice = { text: string; type?: 'error' | 'success' };
const safeArray = (value: unknown): Row[] => Array.isArray(value) ? value : [];

export default function App() {
  const [emailAction, setEmailAction] = useState(() => {
    const params = new URLSearchParams(window.location.hash.slice(1));
    const action = params.get('action');
    const token = params.get('token');
    return action === 'reset' && token ? token : null;
  });
  const [session, setSession] = useState<Session | null>(null);
  const [booting, setBooting] = useState(true);
  const [notice, setNotice] = useState<Notice | null>(null);
  const [dark, setDark] = useState(() => localStorage.getItem('appclase-theme') === 'dark');
  const refresh = useCallback(async () => {
    try { setSession(await api.get<Session>('/me')); } catch { setSession(null); } finally { setBooting(false); }
  }, []);
  useEffect(() => { void refresh(); }, [refresh]);
  useEffect(() => { document.documentElement.dataset.theme = dark ? 'dark' : 'light'; localStorage.setItem('appclase-theme', dark ? 'dark' : 'light'); }, [dark]);
  const flash = useCallback((text: string, type: Notice['type'] = 'success') => { setNotice({ text, type }); window.setTimeout(() => setNotice(null), 3600); }, []);
  if (emailAction) return <PasswordResetPage token={emailAction} onClose={() => {
    window.history.replaceState(null, '', window.location.pathname + window.location.search);
    setEmailAction(null);
    void refresh();
  }}/>;
  if (booting) return <div className="boot"><div className="brand-mark">a.</div><span>Preparando tu espacio…</span></div>;
  if (!session) return <Access onDone={refresh} />;
  if (session.user.must_change === 1) return <Activate onDone={refresh} />;
  return <><Routes>
    <Route element={<Shell session={session} dark={dark} setDark={setDark} onSignOut={async () => { await api.post('/logout'); setSession(null); }} />}>
      <Route path="/" element={<Dashboard session={session} flash={flash} refreshSession={refresh} />} />
      <Route path="/centros" element={<CenterDirectory session={session} flash={flash} refreshSession={refresh} />} />
      <Route path="/centros/:id/*" element={<Center session={session} flash={flash} refreshSession={refresh} />} />
      <Route path="/clases/:id/tareas/:assignmentId" element={<AssignmentPage />} />
      <Route path="/clases/:id/*" element={<Classroom session={session} flash={flash} />} />
      <Route path="/agenda" element={<Agenda />} />
      <Route path="/alumnos" element={<GlobalRoster session={session} />} />
      <Route path="/tareas" element={<Tasks session={session} />} />
      <Route path="/calificaciones" element={<Grades session={session} />} />
      <Route path="/asistencia" element={<Attendance session={session} />} />
      <Route path="/avisos" element={<Notifications flash={flash} />} />
      <Route path="/cuenta" element={<Account session={session} flash={flash} />} />
      <Route path="*" element={<NotFound />} />
    </Route>
  </Routes>{notice && <div className={`toast ${notice.type || ''}`} role="status">{notice.type === 'error' ? <CircleHelp size={17}/> : <Check size={17}/>} {notice.text}</div>}</>;
}

function Access({ onDone }: { onDone: () => void }) {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setBusy(true); setError(''); const data = new FormData(event.currentTarget);
    try {
      if (mode === 'register') await api.register(String(data.get('name')), String(data.get('email')), String(data.get('password')));
      else await api.login(String(data.get('email')), String(data.get('password')), String(data.get('center_code') || '').toUpperCase());
      onDone();
    } catch (e) { setError((e as Error).message); } finally { setBusy(false); }
  };
  return <main className="auth-page"><section className="auth-visual"><div className="auth-brand"><Brand/><span>APPCLASE</span></div><div className="visual-copy"><span className="eyebrow light">APRENDER JUNTOS, LLEGAR MÁS LEJOS</span><h1>Todo lo que<br/>hace crecer<br/><em>una clase.</em></h1><p>Un espacio claro para enseñar, aprender y avanzar en equipo.</p><div className="visual-orbit"><span className="orbit-dot dot-a"><BookOpen size={20}/></span><span className="orbit-dot dot-b"><Users size={18}/></span><span className="orbit-dot dot-c"><Sparkles size={19}/></span><div className="orbit-center"><GraduationCap size={50}/></div></div></div><div className="auth-foot">© 2026 APPCLASE <span>Un espacio propio para cada centro</span></div></section><section className="auth-panel"><div className="auth-form-wrap"><div className="auth-mobile-brand"><Brand/><b>APPCLASE</b></div><span className="eyebrow">TU ESPACIO DE APRENDIZAJE</span><h2>{mode === 'login' ? 'Qué bueno verte.' : 'Crea tu cuenta.'}</h2><p className="muted">{mode === 'login' ? 'Accede con las credenciales de tu centro.' : 'Regístrate para unirte a tu comunidad educativa.'}</p><form onSubmit={submit} className="form-stack">{mode === 'register' && <Field label="Nombre completo" name="name" placeholder="Cómo te llamas" required/>}<Field label="Correo electrónico" name="email" type="email" placeholder="nombre@centro.es" required/><Field label="Contraseña" name="password" type="password" placeholder="Mínimo 12 caracteres" minLength={mode === 'register' ? 12 : 1} required/>{mode === 'login' && <Field label="Código de centro" name="center_code" placeholder="Solo si eres profesor de nuevo acceso" maxLength={4}/>}<Button type="submit" className="button primary full" disabled={busy}>{busy ? <span className="spinner"/> : mode === 'login' ? 'Entrar a APPCLASE' : 'Crear cuenta'}<ArrowRight size={17}/></Button>{error && <div className="error-box">{error}</div>}</form><div className="auth-switch">{mode === 'login' ? '¿Todavía no tienes cuenta?' : '¿Ya tienes cuenta?'} <button onClick={() => { setMode(mode === 'login' ? 'register' : 'login'); setError(''); }}>{mode === 'login' ? 'Crear cuenta' : 'Iniciar sesión'}</button></div>{mode === 'login' && <ResetRequest/>}<div className="secure-note"><ShieldCheck size={17}/> Acceso protegido y privado</div></div></section></main>;
}

function Activate({ onDone }: { onDone: () => void }) {
  const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const data = new FormData(e.currentTarget); if (data.get('password') !== data.get('confirm')) return setError('Las contraseñas no coinciden.'); setBusy(true); try { await api.post('/auth/activate', { password: data.get('password') }); onDone(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  return <main className="activate-page"><div className="auth-card"><Brand/><span className="eyebrow">PRIMER ACCESO</span><h1>Activa tu cuenta</h1><p className="muted">Crea una contraseña personal para proteger tu acceso al centro.</p><form className="form-stack" onSubmit={submit}><Field label="Nueva contraseña" name="password" type="password" minLength={12} required/><Field label="Repite la contraseña" name="confirm" type="password" minLength={12} required/><p className="hint">Usa al menos 12 caracteres. No reutilices la contraseña temporal.</p>{error && <div className="error-box">{error}</div>}<button className="button primary full" disabled={busy}>Guardar contraseña <ArrowRight size={17}/></button></form></div></main>;
}

function Shell({ session, dark, setDark, onSignOut }: { session: Session; dark: boolean; setDark: (v: boolean) => void; onSignOut: () => void }) {
  const loc = useLocation(); const [mobileOpen, setMobileOpen] = useState(false); const isAdmin = session.platform_admin === true;
  const org = session.organizations.find(o => o.role === 'admin' || o.role === 'teacher') || session.organizations[0];
  const role = isAdmin ? 'admin' : org?.role || 'student';
  const items = isAdmin ? [
    ['/', 'Resumen', LayoutDashboard], ['/centros', 'Centros educativos', GraduationCap], ['/agenda', 'Agenda', CalendarDays], ['/alumnos', 'Personas', Users], ['/avisos', 'Actividad', Activity],
  ] as const : role === 'teacher' ? [
    ['/', 'Inicio', LayoutDashboard], ['/agenda', 'Agenda', CalendarDays], ['/tareas', 'Tareas', ClipboardList], ['/alumnos', 'Alumnos', Users], ['/calificaciones', 'Calificaciones', BookOpen], ['/avisos', 'Avisos', Bell],
  ] as const : [
    ['/', 'Inicio', LayoutDashboard], ['/agenda', 'Mi agenda', CalendarDays], ['/tareas', 'Mis tareas', ClipboardList], ['/calificaciones', 'Calificaciones', BookOpen], ['/avisos', 'Avisos', Bell],
  ] as const;
  const active = (path: string) => path === '/' ? loc.pathname === '/' : loc.pathname.startsWith(path);
  return <div className="app-shell"><aside className={`sidebar ${mobileOpen ? 'open' : ''}`}><div className="sidebar-top"><Link className="brand-lockup" to="/"><Brand/><span>APPCLASE<small>ESPACIO EDUCATIVO</small></span></Link><button className="icon-button close-sidebar" onClick={() => setMobileOpen(false)}><X/></button></div><div className="workspace-select"><div className="workspace-icon">{isAdmin ? <ShieldCheck size={17}/> : <GraduationCap size={18}/>}</div><div className="workspace-text"><strong>{isAdmin ? 'Administración global' : org?.name || 'Mi espacio'}</strong><span>{roleName(role)}</span></div><ChevronDown size={15}/></div><div className="side-label">ESPACIO DE TRABAJO</div><nav className="side-nav">{items.map(([path, label, Icon]) => <Link key={path} to={path} onClick={() => setMobileOpen(false)} className={`nav-link ${active(path) ? 'selected' : ''}`}><Icon size={18}/><span>{label}</span>{path === '/avisos' && <i className="nav-ping"/>}</Link>)}</nav>{!isAdmin && <><div className="side-heading"><span>MIS CLASES</span><Link to="/" aria-label="Ver clases"><Plus size={16}/></Link></div><nav className="side-nav class-nav">{session.organizations.slice(0, 1).map(o => <ClassLinks key={o.id} org={o} role={role}/>)}</nav></>}<div className="sidebar-bottom"><button className="nav-link" onClick={() => setDark(!dark)}>{dark ? <Sun size={18}/> : <Moon size={18}/>}<span>{dark ? 'Modo claro' : 'Modo oscuro'}</span></button><Link className="nav-link" to="/cuenta"><Settings size={18}/><span>Mi cuenta</span></Link><div className="profile-mini"><div className="avatar">{initials(session.user.name)}</div><div className="profile-name"><strong>{session.user.name}</strong><span>{roleName(role)}</span></div><button className="icon-button" title="Cerrar sesión" onClick={onSignOut}><LogOut size={17}/></button></div></div></aside>{mobileOpen && <button className="scrim" aria-label="Cerrar menú" onClick={() => setMobileOpen(false)}/>}<div className="main-column"><header className="topbar"><button className="icon-button mobile-menu" onClick={() => setMobileOpen(true)} aria-label="Abrir menú"><Menu/></button><div className="breadcrumb"><span>APPCLASE</span><ChevronRight size={14}/><strong>{pageTitle(loc.pathname)}</strong></div><div className="top-actions"><button className="icon-button search-toggle" title="Buscar"><Search size={19}/></button><Link className="icon-button bell-action" to="/avisos" title="Notificaciones"><Bell size={19}/><i/></Link><div className="top-divider"/><div className="avatar small-avatar">{initials(session.user.name)}</div></div></header><main className="page-body"><Outlet/></main></div><MobileNav role={role} pathname={loc.pathname}/></div>;
}

// Role-aware navigation with dedicated workspace sections.
function ClassLinks({ org, role }: { org: Row; role: string }) {
  const [classes, setClasses] = useState<Row[]>([]);
  useEffect(() => { api.get<Row[]>('/classes').then(rows => setClasses(rows.filter(c => c.org_id === org.id || c.organization === org.name).slice(0, 5))).catch(() => setClasses([])); }, [org.id, org.name]);
  return <>{classes.slice(0, 5).map(c => <Link className="class-nav-link" key={c.id} to={`/clases/${c.id}`}><i className="class-dot agenda-subject-dot" style={{backgroundColor: courseColor(c)}}/><span>{c.name}</span></Link>)}<Link to={role === 'student' ? '/' : '/'} className="class-nav-link muted-link"><Plus size={15}/><span>{classes.length ? 'Ver todas' : 'Sin clases todavía'}</span></Link></>;
}
function MobileNav({ role, pathname }: { role: string; pathname: string }) {
  const links = role === 'admin' ? [['/', 'Inicio', LayoutDashboard], ['/agenda', 'Agenda', CalendarDays], ['/avisos', 'Actividad', Activity], ['/cuenta', 'Cuenta', Users]] : [['/', 'Inicio', LayoutDashboard], ['/agenda', 'Agenda', CalendarDays], ['/tareas', 'Tareas', ClipboardList], ['/avisos', 'Avisos', Bell]];
  return <nav className="mobile-nav">{links.map(([path, label, Icon]) => <Link key={path as string} to={path as string} className={pathname === path ? 'active' : ''}><Icon size={20}/><span>{label as string}</span></Link>)}</nav>;
}

function Dashboard({ session, flash, refreshSession }: { session: Session; flash: (s: string) => void; refreshSession: () => void | Promise<void> }) {
  const [classes, setClasses] = useState<Row[]>([]); const [upcoming, setUpcoming] = useState<Row[]>([]); const [centers, setCenters] = useState<Row[]>([]); const [loading, setLoading] = useState(true);
  const admin = session.platform_admin === true; const org = session.organizations.find(o => o.role === 'teacher' || o.role === 'admin'); const role = admin ? 'admin' : org?.role || 'student';
  const load = useCallback(async () => { setLoading(true); const results = await Promise.allSettled([api.get<Row[]>('/classes'), api.get<Row[]>('/dashboard/upcoming'), admin ? api.get<Row[]>('/organizations') : Promise.resolve([])]); if (results[0].status === 'fulfilled') setClasses(results[0].value); if (results[1].status === 'fulfilled') setUpcoming(results[1].value); if (results[2].status === 'fulfilled') setCenters(results[2].value); setLoading(false); }, [admin]);
  useEffect(() => { void load(); }, [load]);
  const createCenter = () => openForm('Crear centro educativo', [{name:'name',label:'Nombre del centro',required:true}], async d => { const created = await api.post<Row>('/organizations', d); await Promise.all([load(), refreshSession()]); return `Centro creado · código ${created.access_code}`; }).then(message => message && flash(message));
  const createClass = () => openForm('Crear clase', [{name:'name',label:'Nombre de la clase',required:true},{name:'subject',label:'Asignatura',required:true,maxLength:120}, subjectColorField(),{name:'academic_year',label:'Curso académico',value:'2026–2027'}], async d => { const target = org || session.organizations[0]; await api.post('/classes', {...d, org_id: target?.id}); await load(); return 'Clase creada correctamente.'; }).then(message => message && flash(message));
  const [searchParams, setSearchParams] = useSearchParams();
  const invitation = searchParams.get('invitacion');
  const joinClass = () => openForm('Unirme a una clase', [{name:'code',label:'Código de invitación',required:true,value:invitation || ''}], async d => { await api.post('/join', d); if(invitation) setSearchParams(previous => { const next = new URLSearchParams(previous); next.delete('invitacion'); return next; }, { replace:true }); await load(); return 'Ya formas parte de la clase.'; }).then(message => message && flash(message));
  return <div className="content-wrap"><div className="welcome-row"><div><div className="eyebrow">{formatToday()}</div><h1>{greeting()}, {session.user.name?.split(' ')[0] || 'bienvenido'} <span className="wave">✳</span></h1><p className="muted">{admin ? 'Aquí tienes una visión global de tus centros.' : role === 'teacher' ? 'Tu espacio docente está listo para hoy.' : 'Este es tu espacio para aprender a tu ritmo.'}</p></div><div className="welcome-actions">{admin && <button className="button primary" onClick={createCenter}><Plus size={17}/> Nuevo centro</button>}{role === 'teacher' && <button className="button primary" onClick={createClass}><Plus size={17}/> Crear clase</button>}{role === 'student' && <button className="button primary" onClick={joinClass}><Plus size={17}/> {invitation ? 'Aceptar invitación' : 'Unirme a una clase'}</button>}</div></div>
    <div className="stat-grid">{(admin ? [{title:'Centros educativos',value:centers.length,icon:GraduationCap,accent:'green',foot:'En toda la plataforma'},{title:'Profesores',value:centers.reduce((a,c)=>a+Number(c.teachers||0),0),icon:Users,accent:'blue',foot:'Con acceso activo'},{title:'Alumnos',value:centers.reduce((a,c)=>a+Number(c.students||0),0),icon:BookOpen,accent:'violet',foot:'En todos los centros'},{title:'Clases activas',value:classes.filter(c=>!c.archived).length,icon:ClipboardList,accent:'amber',foot:'Espacios en curso'}] : [{title:'Mis clases',value:classes.filter(c=>!c.archived).length,icon:BookOpen,accent:'green',foot:role==='teacher'?'Clases a tu cargo':'Clases en las que participas'},{title:role==='teacher'?'Alumnos':'Tareas pendientes',value:role==='teacher'?classes.reduce((n,c)=>n+Number(c.student_count||0),0):upcoming.filter(a=>a.type==='assignment').length,icon:Users,accent:'blue',foot:role==='teacher'?'En tus clases':'Por entregar'},{title:'Próximos hitos',value:upcoming.length,icon:CalendarDays,accent:'violet',foot:'En los próximos 30 días'},{title:'Avisos nuevos',value:'—',icon:Bell,accent:'amber',foot:'Al día con tu espacio'}]).map((s,i)=><div className="stat-card" key={s.title}><div className={`stat-icon ${s.accent}`}><s.icon size={19}/></div><span className="stat-label">{s.title}</span><strong>{loading?<span className="skeleton number"/>:s.value}</strong><small>{s.foot}</small><span className="stat-index">0{i+1}</span></div>)}</div>
    <div className="dashboard-grid"><section className="panel classes-panel"><PanelHead kicker={admin?'TU ORGANIZACIÓN':'ESPACIO DE TRABAJO'} title={admin?'Centros educativos':role==='teacher'?'Tus clases':'Mis clases'} action={admin ? undefined : <Link to="/agenda" className="text-link">Ver agenda <ArrowRight size={15}/></Link>}/>{loading?<RowsSkeleton/>:admin?<div className="center-list">{centers.length?centers.map(c=><Link to={`/centros/${c.id}`} className="center-row" key={c.id}><div className="center-mark"><GraduationCap size={21}/></div><div className="row-main"><strong>{c.name}</strong><span>Código de acceso · <b>{c.access_code}</b></span></div><div className="center-counts"><span><Users size={15}/>{c.teachers} profesores</span><span><BookOpen size={15}/>{c.students} alumnos</span></div><ChevronRight size={17}/></Link>):<Empty title="Todavía no hay centros" detail="Crea el primer espacio educativo para empezar."/>}</div>:classes.length?<div className="class-grid">{classes.slice(0, 6).map((c,i)=><ClassCard key={c.id} item={c} index={i}/>)}</div>:<Empty title="Tu espacio empieza aquí" detail={role==='teacher'?'Crea tu primera clase y reúne a tu comunidad.':'Cuando te unas a una clase, aparecerá aquí.'}/>}</section><section className="panel upcoming-panel"><PanelHead kicker="LO QUE VIENE" title="Próximas fechas" action={<Link to="/agenda" className="icon-link" aria-label="Abrir agenda"><ArrowRight size={17}/></Link>}/>{loading?<RowsSkeleton/>:upcoming.length?<div className="upcoming-list">{upcoming.slice(0,5).map((item,i)=><Link to={item.type==='assignment' && item.class_id ? assignmentLink(item.class_id,item.id) : item.class_id ? `/clases/${item.class_id}` : '/agenda'} className="upcoming-row" key={item.id}><div className={`date-tile tile-${i%4}`}><b>{dateLabel(item.date).split(' ')[0]}</b><span>{dateLabel(item.date).split(' ').slice(1).join(' ')}</span></div><div className="row-main"><strong>{item.title}</strong><span>{item.name} · {item.type==='exam'?'Examen':'Entrega'}</span></div><ChevronRight size={16}/></Link>)}</div>:<Empty title="Todo al día" detail="Las próximas tareas y exámenes aparecerán aquí."/>}</section></div>
    {!admin && <section className="panel quick-panel"><PanelHead kicker="ACCESOS RÁPIDOS" title="¿Qué necesitas hacer?"/><div className="quick-actions">{(role==='teacher'?[['/tareas','Crear una tarea','Prepara la próxima actividad',ClipboardList],['/alumnos','Ver mis alumnos','Sigue el progreso de tu clase',Users],['/calificaciones','Poner calificaciones','Consulta y actualiza notas',BookOpen]]:[['/tareas','Ver mis tareas','Revisa lo que tienes por entregar',ClipboardList],['/calificaciones','Mis calificaciones','Consulta tu progreso',BookOpen],['/avisos','Centro de avisos','No te pierdas ninguna novedad',Bell]]).map(([to,title,desc,Icon])=><Link className="quick-card" to={to as string} key={title as string}><span className="quick-icon"><Icon size={19}/></span><span><strong>{title as string}</strong><small>{desc as string}</small></span><ArrowRight size={16}/></Link>)}</div></section>}
  </div>;
}

function ClassCard({ item, index }: { item: Row; index: number }) { return <Link to={`/clases/${item.id}`} className={`course-card course-${index%4}`}><div className="course-cover"><div className="cover-orb"/><span className="course-subject">{item.subject || 'CLASE'}</span><span className="course-glyph">{['a','b','c','d'][index%4]}</span></div><div className="course-info"><strong>{item.name}</strong><span>{item.organization || item.academic_year || 'Tu espacio de clase'}</span><div className="course-footer"><span><Users size={14}/>{item.student_count ?? '—'} participantes</span><span className="course-arrow"><ArrowRight size={16}/></span></div></div></Link>; }

function CenterDirectory({session,flash,refreshSession}:{session:Session;flash:(s:string)=>void;refreshSession:()=>void|Promise<void>}) {
  const centers=useData<Row[]>('/organizations');const classes=useData<Row[]>('/classes');
  if(!session.platform_admin)return <Navigate to="/" replace/>;
  const create=()=>openForm('Crear centro educativo',[{name:'name',label:'Nombre del centro',required:true}],async d=>{const center=await api.post<Row>('/organizations',d);await Promise.all([centers.reload(),classes.reload(),refreshSession()]);return `Centro creado · código ${center.access_code}`;}).then(result=>result&&flash(result));
  return <div className="content-wrap"><PageHeader kicker="GESTIÓN GLOBAL" title="Centros educativos" subtitle="Gestiona los espacios, equipos y comunidades de APPCLASE."/><section className="panel"><PanelHead kicker="TODOS TUS CENTROS" title={`${safeArray(centers.data).length} centros`} action={<button className="button primary small-button" onClick={create}><Plus size={16}/> Crear centro</button>}/>{centers.loading?<RowsSkeleton/>:safeArray(centers.data).length?<div className="center-list">{safeArray(centers.data).map((center,i)=>{const total=safeArray(classes.data).filter(c=>c.org_id===center.id&&!c.archived).length;return <Link to={`/centros/${center.id}`} className="center-row directory-row" key={center.id}><div className={`center-mark center-mark-${i%4}`}><GraduationCap size={21}/></div><div className="row-main"><strong>{center.name}</strong><span>Código de acceso · <b>{center.access_code}</b></span></div><div className="center-counts"><span><Users size={15}/>{center.teachers||0} profesores</span><span><BookOpen size={15}/>{center.students||0} alumnos</span><span><ClipboardList size={15}/>{total} clases</span></div><ChevronRight size={17}/></Link>})}</div>:<Empty title="Aún no tienes centros" detail="Crea el primer centro para empezar a organizar clases y equipos."/>}</section></div>;
}

function Center({ session, flash, refreshSession }: { session: Session; flash: (s: string, type?: 'error'|'success')=>void; refreshSession: () => void | Promise<void> }) {
  const {id=''}=useParams(); const org=session.organizations.find(o=>o.id===id&&o.role==='admin'); const [section,setSection]=useState('overview'); const [members,setMembers]=useState<Row[]>([]); const [classList,setClassList]=useState<Row[]>([]); const [busy,setBusy]=useState(false);
  const load=useCallback(async()=>{if(!org)return;try{const [memberRows,classes]=await Promise.all([api.get<Row[]>(`/organizations/${id}/members`),api.get<Row[]>('/classes')]);setMembers(memberRows);setClassList(classes.filter(c=>c.org_id===id));}catch(e){flash((e as Error).message,'error');}},[id,org,flash]); useEffect(()=>{void load();},[load]);
  if(!session.platform_admin)return <Navigate to="/" replace/>;
  if(!org){return <div className="content-wrap"><Link to="/" className="back-link"><ArrowLeft size={16}/> Volver a los centros</Link><div className="empty-state"><h2>Centro no disponible</h2><p>Este espacio no existe o no tienes acceso.</p></div></div>}
  const teachers=members.filter(m=>m.role==='teacher'), students=members.filter(m=>m.role==='student');
  const provision=async()=>{const msg=await openForm('Crear cuenta de profesor',[{name:'name',label:'Nombre completo',required:true},{name:'email',label:'Correo electrónico',type:'email',required:true}],async d=>{const invite=await api.post<Row>(`/organizations/${id}/teachers`,d);await load();return `Nombre: ${invite.name}\nCorreo: ${invite.email}\nCódigo del centro: ${invite.access_code}\nContraseña temporal: ${invite.password}`;});if(msg)await openDetails('Datos de primer acceso',msg);};
  const createClass=async()=>{const msg=await openForm('Crear clase',[{name:'name',label:'Nombre de la clase',required:true},{name:'subject',label:'Asignatura',required:true,maxLength:120}, subjectColorField(),{name:'academic_year',label:'Curso académico',value:'2026–2027'},{name:'description',label:'Descripción',textarea:true}],async d=>{await api.post('/classes',{...d,org_id:id});await load();return 'La clase ya está disponible en este centro.';});if(msg)flash(msg);};
  const manage=async(role:string,user?:Row)=>{const msg=await openForm(user?`Vincular a ${user.name}`:`Añadir ${roleName(role).toLowerCase()}`,[{name:'user_id',label:'ID de cuenta APPCLASE',required:true,value:user?.id}],async d=>{await api.post(`/organizations/${id}/members`,{...d,role,active:true});await load();return 'Acceso actualizado.';});if(msg)flash(msg);};
  const toggle=async(user:Row)=>{setBusy(true);try{await api.post(`/organizations/${id}/members`,{user_id:user.id,role:user.role,active:!user.active});await load();flash(user.active?'Acceso desactivado.':'Acceso restaurado.');}catch(e){flash((e as Error).message,'error');}finally{setBusy(false)}};
  return <div className="content-wrap"><Link to="/" className="back-link"><ArrowLeft size={16}/> Todos los centros</Link><div className="center-hero"><div className="center-emblem"><GraduationCap size={28}/></div><div className="center-hero-copy"><span className="eyebrow">ESPACIO EDUCATIVO · ACTIVO</span><h1>{org.name}</h1><p>Código de acceso <b className="code-chip">{org.access_code}</b></p></div><button className="button soft" onClick={()=>void openForm('Editar centro',[{name:'name',label:'Nombre del centro',required:true,value:org.name}],async d=>{await api.post(`/organizations/${id}/settings`,d);await Promise.all([load(),refreshSession()]);return 'Centro actualizado.';}).then(m=>m&&flash(m))}><Settings size={16}/> Configurar</button></div><div className="section-tabs">{[['overview','Resumen'],['classes','Clases'],['teachers','Profesores'],['students','Alumnos'],['reports','Informes'],['activity','Actividad']].map(([key,title])=><button key={key} className={section===key?'active':''} onClick={()=>setSection(key)}>{title}{key==='classes'?` · ${classList.length}`:key==='teachers'?` · ${teachers.length}`:key==='students'?` · ${students.length}`:''}</button>)}</div>
    {section==='overview'&&<><div className="stat-grid compact">{[['Profesores',teachers.length,Users,'green'],['Alumnos',students.length,BookOpen,'blue'],['Clases activas',classList.filter(c=>!c.archived).length,ClipboardList,'violet'],['Código del centro',org.access_code,ShieldCheck,'amber']].map(([title,value,Icon,color])=><div className="stat-card" key={title as string}><div className={`stat-icon ${color}`}><Icon size={18}/></div><span className="stat-label">{title as string}</span><strong className={title==='Código del centro'?'code-value':''}>{value as string|number}</strong><small>{title==='Código del centro'?'Compártelo con el equipo docente':'Acceso activo'}</small></div>)}</div><div className="dashboard-grid"><section className="panel"><PanelHead kicker="EQUIPO DOCENTE" title="Profesores" action={<button className="text-link" onClick={()=>setSection('teachers')}>Ver equipo <ArrowRight size={15}/></button>}/><PeopleList people={teachers.slice(0,4)} empty="Aún no hay profesores vinculados."/></section><section className="panel"><PanelHead kicker="COMUNIDAD" title="Alumnos" action={<button className="text-link" onClick={()=>setSection('students')}>Ver alumnos <ArrowRight size={15}/></button>}/><PeopleList people={students.slice(0,4)} empty="Aún no hay alumnos en este centro."/></section></div></>}
    {section==='classes'&&<section className="panel"><PanelHead kicker="ESPACIOS DE APRENDIZAJE" title="Clases del centro" action={<button className="button primary small-button" onClick={createClass}><Plus size={16}/> Crear clase</button>}/>{classList.length?<div className="class-grid">{classList.map((c,i)=><ClassCard item={c} index={i} key={c.id}/>)}</div>:<Empty title="Empieza creando una clase" detail="Las clases y sus contenidos se gestionan dentro de este centro."/>}</section>}
    {section==='teachers'&&<section className="panel"><PanelHead kicker="GESTIÓN DE ACCESOS" title="Profesores" action={<button className="button primary small-button" onClick={provision}><Plus size={16}/> Crear profesor</button>}/><PeopleList people={teachers} empty="Crea la primera cuenta docente para este centro." onToggle={toggle} busy={busy}/></section>}
    {section==='students'&&<section className="panel"><PanelHead kicker="GESTIÓN DE ACCESOS" title="Alumnos" action={<button className="button soft small-button" onClick={()=>manage('student')}><Plus size={16}/> Añadir por ID</button>}/><PeopleList people={students} empty="Los alumnos se incorporarán desde sus clases." onToggle={toggle} busy={busy}/></section>}
    {section==='reports'&&<section className="panel"><PanelHead kicker="RESUMEN DEL CENTRO" title="Informes"/><div className="report-grid"><ReportTile icon={Users} title="Miembros activos" value={teachers.length+students.length} detail="Profesores y alumnos"/><ReportTile icon={BookOpen} title="Equipo docente" value={teachers.length} detail="Con acceso al centro"/><ReportTile icon={GraduationCap} title="Comunidad de alumnos" value={students.length} detail="Con acceso al centro"/></div></section>}
    {section==='activity'&&<section className="panel"><PanelHead kicker="REGISTRO DEL CENTRO" title="Actividad reciente"/><Records path={`/organizations/${id}/audit`} empty="La actividad de este centro aparecerá aquí."/></section>}
  </div>;
}

function Classroom({session,flash}:{session:Session;flash:(s:string,type?:'error'|'success')=>void}) {
 const {id=''}=useParams();const [course,setCourse]=useState<Row|null>(null);const [section,setSection]=useState('board');const [rows,setRows]=useState<Row[]>([]);const [busy,setBusy]=useState(false);const load=useCallback(async()=>{try{const c=await api.get<Row>(`/classes/${id}`);setCourse(c);const query=section==='calendar'?calendarQuery(new Date()):'';if (['attendance','exams'].includes(section)) return;const data=await api.get<Row[]>(`/classes/${id}/${section}${query}`);setRows(data);}catch(e){flash((e as Error).message,'error');}},[id,section,flash]);useEffect(()=>{void load();},[load]);
 if(!course)return <div className="content-wrap"><div className="skeleton hero-skeleton"/><RowsSkeleton/></div>;
 const staff=course.role!=='student';const tabs=[['board','Tablón',MessageSquare],['topics','Temario',BookOpen],['assignments','Tareas',ClipboardList],['exams','Exámenes',Sparkles],...(staff?[['students','Alumnos',Users] as const]:[]),['grades','Calificaciones',Activity],['attendance','Asistencia',Check],['calendar','Calendario',CalendarDays],['materials','Archivos',BookOpen],['messages','Mensajes',MessageSquare]].map(([k,l,I])=>({key:k as string,label:l as string,Icon:I as typeof BookOpen}));
 const change=async(action:string,data:Row={})=>{try{setBusy(true);const result=await api.post<Row>(`/classes/${id}/${action}`,data);if(action==='invite')await navigator.clipboard?.writeText(`${location.origin}/?invitacion=${result.code}`);flash(action==='invite'?`Invitación copiada: ${result.code}`:'Cambios guardados.');await load();}catch(e){flash((e as Error).message,'error');}finally{setBusy(false)}};
 const create=async()=>{const cfg=section==='assignments'?[{name:'title',label:'Título',required:true},{name:'body',label:'Instrucciones',required:true,textarea:true},{name:'due',label:'Fecha límite',type:'datetime-local',required:true},{name:'points',label:'Puntuación máxima',type:'number',value:'10',required:true},{name:'allow_late',label:'Aceptar entregas fuera de plazo',type:'checkbox'}]:section==='board'?[{name:'body',label:'Escribe un anuncio para la clase',required:true,textarea:true}]:section==='calendar'?[{name:'title',label:'Título',required:true},{name:'body',label:'Descripción',textarea:true},{name:'start',label:'Inicio',type:'datetime-local',required:true},{name:'finish',label:'Fin',type:'datetime-local',required:true}]:[{name:'title',label:'Título',required:true},{name:'body',label:'Descripción',textarea:true}];await openForm(section==='assignments'?'Crear tarea':section==='board'?'Publicar anuncio':`Añadir ${tabs.find(t=>t.key===section)?.label.toLowerCase()||'contenido'}`,cfg,async d=>{const payload={...d};for(const field of ['due','start','finish']) if(payload[field])payload[field]=Math.floor(new Date(payload[field]).getTime()/1000);if(section==='assignments'){payload.points=Number(payload.points);payload.allow_late=d.allow_late==='on';}if(section==='board')await api.post(`/classes/${id}/posts`,payload);else await api.post(`/classes/${id}/${section}`,payload);await load();return 'Contenido publicado correctamente.';}).then(m=>m&&flash(m));};
 const editColor = async () => {
   const message = await openForm('Cambiar color de la asignatura', [subjectColorField(courseColor(course))], async data => {
     const result = await api.post<Row>(`/classes/${id}/subject-color`, data);
     setCourse({ ...course, subject_color: result.subject_color });
     return 'Color actualizado para la asignatura en este centro.';
   });
   if (message) flash(message);
 };
 const title=course.name||'Mi clase';
 return <div className="content-wrap class-content"><Link to="/" className="back-link"><ArrowLeft size={16}/> Volver al inicio</Link><div className={`class-hero theme-${Math.abs(String(course.id).charCodeAt(0))%4}`}><div className="hero-art"><span/><span/><span/></div><div className="class-hero-copy"><span className="eyebrow light">{course.subject||'ESPACIO DE CLASE'} · {course.academic_year||'CURSO ACTIVO'}</span><h1>{title}</h1><p>{course.description||'Un lugar para aprender, compartir y avanzar en equipo.'}</p></div><button className="hero-menu" onClick={()=>staff&&void change('invite')} disabled={!staff||busy} title="Generar invitación" aria-label="Generar enlace de invitación"><MoreHorizontal/></button></div><div className="class-tabs">{tabs.map(({key,label,Icon})=><button key={key} className={section===key?'active':''} onClick={()=>setSection(key)}><Icon size={16}/>{label}</button>)}</div><div className="class-toolbar"><div><span className="eyebrow">{section.toUpperCase()}</span><h2>{({board:'Novedades de la clase',topics:'Temario y recursos',assignments:'Tareas de la clase',exams:'Exámenes',students:'Personas matriculadas',grades:'Cuaderno de calificaciones',attendance:'Control de asistencia',calendar:'Calendario de clase',materials:'Materiales compartidos',messages:'Conversaciones'} as Record<string,string>)[section]}</h2></div><div className="toolbar-actions">{staff && !course.archived && <button className="button soft small-button" onClick={editColor}><i className="class-dot agenda-subject-dot" style={{backgroundColor: courseColor(course)}}/>Cambiar color</button>}{staff&&!course.archived&&!['attendance','exams','students'].includes(section)&&<button className="button primary small-button" onClick={create}><Plus size={16}/>{section==='board'?'Publicar':section==='assignments'?'Crear tarea':'Añadir'}</button>}</div></div>
 {section === 'materials' && <section className="panel mb-4">{course.documents_enabled ? <ClassDocuments key={id} path={`/classes/${id}`} canUpload={staff && !course.archived}/> : <p className="muted">El almacenamiento de documentos privados aún no está habilitado.</p>}</section>}
 <section className="panel class-list-panel">{section==='students'?<>{staff && !course.archived && <ClassRosterImport path={`/classes/${id}`} onImported={load}/>}
  {rows.length ? <ul className="record-list">{rows.map(student => <li className="record-row" key={student.id}>{student.name}</li>)}</ul> : <Empty title="Todavía no hay alumnos en esta clase" detail=""/>}</>:section==='grades'?<Records path={`/classes/${id}/grades`} empty="Las calificaciones aparecerán cuando haya tareas corregidas."/>:section==='attendance'?<ClassAttendance key={id} path={`/classes/${id}`} staff={staff} archived={Boolean(course.archived)}/>:section==='exams'?<ClassExams key={id} path={`/classes/${id}`} staff={staff} archived={Boolean(course.archived)}/>:section==='calendar'?<AgendaRows rows={rows.map(row=>({...row,date:row.start,type:row.kind,class_id:id}))}/>:section==='messages'?<Records path={`/classes/${id}/messages`} empty="Todavía no hay conversaciones."/>:rows.length?<div className="feed-list">{rows.map((r,i)=><article className="feed-card" key={r.id||i}><div className="feed-avatar">{section==='board'?<MessageSquare size={17}/>:section==='assignments'?<ClipboardList size={17}/>:<BookOpen size={17}/>}</div><div className="feed-content"><div className="feed-meta"><b>{r.author_name||r.teacher_name||'APPCLASE'}</b><span>{dateLabel(r.created_at||r.due||r.date)}</span></div><h3>{r.title||r.name||'Publicación de clase'}</h3><p>{r.body||r.description||r.subject||'Consulta este elemento para ver más detalles.'}</p>{r.type&&<span className="status-pill">{r.type==='exam'?'Examen':'Entrega'}</span>}</div>{section==='assignments'&&<Link className="button soft small-button" to={assignmentLink(id,r.id)}>{staff?'Revisar':'Abrir tarea'}</Link>}</article>)}</div>:<Empty title="Aún no hay contenido" detail={staff?'Añade el primer elemento para que tu clase pueda empezar.':'El profesor todavía no ha publicado contenido en este apartado.'}/>}</section>
 </div>;
}

function Agenda() {
  const [weekly, setWeekly] = useState(false);
  const week = useData<Row[]>(weekly ? '/dashboard/upcoming?period=week' : '');
  return <div className="content-wrap">
    <PageHeader kicker="CALENDARIO" title="Agenda" subtitle="Tareas, exámenes y eventos de tus asignaturas."/>
    <div className="flex gap-2 mb-4" aria-label="Vista de agenda">
      <button className={'button ' + (!weekly ? 'primary' : 'soft')} aria-pressed={!weekly} onClick={() => setWeekly(false)}>Calendario mensual</button>
      <button className={'button ' + (weekly ? 'primary' : 'soft')} aria-pressed={weekly} onClick={() => setWeekly(true)}>Próximos 7 días</button>
    </div>
    {weekly ? <section className="panel">
      <h2 className="mb-3">Resumen semanal</h2>
      {week.loading ? <p role="status">Cargando agenda…</p> : week.error ? <p className="error-box" role="alert">{week.error}</p>
        : <AgendaRows rows={safeArray(week.data)} emptyTitle="No hay actividades previstas esta semana"/>}
    </section> : <AgendaCalendar renderRows={rows => <AgendaRows rows={rows} emptyTitle="No hay fechas para este periodo"/>}/>}
  </div>;
}

function GlobalRoster({session}:{session:Session}) { const [rows,setRows]=useState<Row[]>([]);const classes=useData<Row[]>('/classes');useEffect(()=>{const requests=safeArray(classes.data).map(c=>api.get<Row[]>(`/classes/${c.id}/students`));Promise.allSettled(requests).then(results=>setRows(results.flatMap(r=>r.status==='fulfilled'?r.value:[])));},[classes.data]);return <div className="content-wrap"><PageHeader kicker="COMUNIDAD" title={session.platform_admin?'Personas y centros':'Mis alumnos'} subtitle="Consulta las personas que forman parte de tus espacios educativos."/><section className="panel"><PanelHead kicker="LISTADO" title={`${rows.length} ${session.platform_admin?'personas':'alumnos'}`}/><PeopleList people={rows} empty="Todavía no hay personas vinculadas a tus clases."/></section></div>}

function Tasks({session}:{session:Session}) { const courses=useData<Row[]>('/classes');const [rows,setRows]=useState<Row[]>([]);useEffect(()=>{Promise.allSettled(safeArray(courses.data).map(c=>api.get<Row[]>(`/classes/${c.id}/assignments`).then(tasks => tasks.map(task => ({ ...task, type: 'assignment', name: c.subject }))))).then(results=>setRows(results.flatMap(r=>r.status==='fulfilled'?r.value:[])));},[courses.data]);const upcoming=useData<Row[]>('/dashboard/upcoming');const list=rows.length?rows:safeArray(upcoming.data).filter(x=>x.type==='assignment');return <div className="content-wrap"><PageHeader kicker={session.organizations.some(o=>o.role==='teacher')?'SEGUIMIENTO DOCENTE':'ORGANIZA TU TRABAJO'} title={session.organizations.some(o=>o.role==='teacher')?'Tareas de mis clases':'Mis tareas'} subtitle="Revisa las actividades y mantén el ritmo de aprendizaje."/><section className="panel"><PanelHead kicker="ACTIVIDADES" title="Todas las tareas"/><AgendaRows rows={list} emptyTitle="No hay tareas pendientes"/></section></div>}

function Grades({session}:{session:Session}) {const courses=useData<Row[]>('/classes');const [rows,setRows]=useState<Row[]>([]);useEffect(()=>{Promise.allSettled(safeArray(courses.data).map(c=>api.get<Row[]>(`/classes/${c.id}/grades`))).then(results=>setRows(results.flatMap(r=>r.status==='fulfilled'?r.value:[])));},[courses.data]);return <div className="content-wrap"><PageHeader kicker="PROGRESO ACADÉMICO" title="Calificaciones" subtitle={session.organizations.some(o=>o.role==='teacher')?'Consulta el progreso de tus alumnos.':'Consulta tus resultados y comentarios.'}/><section className="panel"><PanelHead kicker="EVALUACIÓN" title="Actividad reciente"/>{rows.length?<div className="table-wrap"><table><thead><tr><th>{session.organizations.some(o=>o.role==='teacher')?'Alumno':'Actividad'}</th><th>Clase</th><th>Resultado</th><th>Fecha</th></tr></thead><tbody>{rows.map((r,i)=><tr key={r.id||i}><td><strong>{r.student_name||r.title||'Actividad evaluada'}</strong><small>{r.feedback||'—'}</small></td><td>{r.class_name||'—'}</td><td><span className="grade-chip">{r.score??'—'}{r.points?` / ${r.points}`:''}</span></td><td>{dateLabel(r.date||r.updated_at)}</td></tr>)}</tbody></table></div>:<Empty title="Aún no hay calificaciones" detail="Las notas aparecerán aquí cuando haya actividades evaluadas."/>}</section></div>}

function Attendance({session}:{session:Session}) { const courses=useData<Row[]>('/classes');const [rows,setRows]=useState<Row[]>([]);useEffect(()=>{Promise.allSettled(safeArray(courses.data).map(c=>api.get<Row[]>(`/classes/${c.id}/attendance`))).then(results=>setRows(results.flatMap(r=>r.status==='fulfilled'?r.value:[])));},[courses.data]);return <div className="content-wrap"><PageHeader kicker="SEGUIMIENTO" title="Asistencia" subtitle="Registro de asistencia de tus clases."/><section className="panel"><PanelHead kicker="REGISTROS" title="Actividad reciente"/>{rows.length?<AgendaRows rows={rows}/>:<Empty title="Sin registros todavía" detail="Los registros de asistencia aparecerán aquí."/>}</section></div>}

function Notifications({flash}:{flash:(s:string,type?:'error'|'success')=>void}) {const data=useData<Row[]>('/notifications');const mark=async(id:string)=>{try{await api.post('/notifications/read',{id});data.reload();}catch(e){flash((e as Error).message,'error')}};return <div className="content-wrap"><PageHeader kicker="AL DÍA CONTIGO" title="Centro de avisos" subtitle="Novedades, mensajes y recordatorios de tus clases."/><section className="panel"><PanelHead kicker="RECIENTES" title="Tus notificaciones"/>{data.loading?<RowsSkeleton/>:safeArray(data.data).length?<div className="feed-list">{safeArray(data.data).map((r,i)=><div className={`notice-row ${r.read?'read':''}`} key={r.id||i}><div className="notice-icon"><Bell size={17}/></div><div className="row-main"><strong>{r.title||r.type||'Aviso de APPCLASE'}</strong><span>{r.body||r.message||'Tienes una novedad en tu espacio educativo.'}</span><small>{dateLabel(r.created_at)}</small></div>{!r.read&&<button className="button soft small-button" onClick={()=>mark(r.id)}>Marcar leído</button>}</div>)}</div>:<Empty title="Estás al día" detail="Cuando haya novedades, te avisaremos por aquí."/>}</section></div>}

function Account({session,flash}:{session:Session;flash:(s:string,type?:'error'|'success')=>void}) {return <div className="content-wrap"><PageHeader kicker="TU ESPACIO PERSONAL" title="Mi cuenta" subtitle="Revisa la información de acceso de tu perfil."/><div className="account-grid"><section className="panel account-profile"><div className="profile-large">{initials(session.user.name)}</div><span className="eyebrow">PERFIL APPCLASE</span><h2>{session.user.name}</h2><p>{session.user.email}</p><span className="status-pill">{session.platform_admin?'Administrador de plataforma':roleName(session.organizations[0]?.role)}</span><div className="account-id"><small>ID DE CUENTA</small><code>{session.user.id}</code></div></section><section className="panel"><PanelHead kicker="SEGURIDAD" title="Acceso y sesión"/><div className="setting-row"><div><strong>Contraseña</strong><span>Actualiza tus credenciales de acceso</span></div><button className="button soft small-button" onClick={()=>void openForm('Cambiar contraseña',[{name:'current_password',label:'Contraseña actual',type:'password',required:true},{name:'password',label:'Nueva contraseña',type:'password',required:true}],async d=>{await api.post('/auth/password',d);return 'Contraseña actualizada.';}).then(m=>m&&flash(m))}>Cambiar</button></div><div className="setting-row"><div><strong>Sesión segura</strong><span>Tu conexión está protegida con una cookie HttpOnly</span></div><ShieldCheck className="good-icon" size={20}/></div></section></div></div>}

function useData<T>(path:string) {const [data,setData]=useState<T>();const [loading,setLoading]=useState(true);const [error,setError]=useState('');const reload=useCallback(()=>{if(!path)return;setLoading(true);setError('');api.get<T>(path).then(setData).catch(e=>setError((e as Error).message)).finally(()=>setLoading(false));},[path]);useEffect(()=>{reload();},[reload]);return {data,loading,error,reload};}
function Records({path,empty}:{path:string;empty:string}) {const data=useData<Row[]>(path);return data.loading?<RowsSkeleton/>:safeArray(data.data).length?<div className="record-list">{safeArray(data.data).map((r,i)=><div className="record-row" key={r.id||i}><span className="record-dot"/><div className="row-main"><strong>{r.title||r.name||r.action||'Registro'}</strong><span>{r.body||r.description||r.detail||r.email||''}</span></div><small>{dateLabel(r.created_at||r.timestamp||r.date)}</small></div>)}</div>:<Empty title={empty} detail=""/>}
function PeopleList({people,empty,onToggle,busy=false}:{people:Row[];empty:string;onToggle?:(u:Row)=>void;busy?:boolean}) {return people.length?<div className="people-list">{people.map((p,i)=><div className="person-row" key={p.id||i}><div className={`avatar person-avatar person-${i%5}`}>{initials(p.name)}</div><div className="row-main"><strong>{p.name||p.email||'Cuenta APPCLASE'}</strong><span>{p.email||roleName(p.role)}{p.role?` · ${roleName(p.role)}`:''}</span></div><span className={`member-status ${p.active===0?'inactive':''}`}><i/>{p.active===0?'Inactivo':'Activo'}</span>{onToggle&&<button className="button text-button" disabled={busy||p.role==='admin'} onClick={()=>onToggle(p)}>{p.active===0?'Restaurar':'Desactivar'}</button>}</div>)}</div>:<Empty title={empty} detail=""/>}
function AgendaRows({rows,emptyTitle='No hay fechas próximas'}:{rows:Row[];emptyTitle?:string}) {const ordered=[...rows].sort((a,b)=>Number(a.date||a.due||a.created_at||0)-Number(b.date||b.due||b.created_at||0));return ordered.length?<div className="timeline-list">{ordered.map((r,i)=><Link to={r.class_id ? r.type === 'assignment' ? assignmentLink(r.class_id, r.assignmentId || r.id) : `/clases/${r.class_id}` : '#'} className="timeline-row" key={r.id||i}><div className={`date-tile tile-${i%4}`} style={r.subjectColor ? {border: `2px solid ${r.subjectColor}`} : undefined}><b>{dateLabel(r.date||r.due||r.created_at).split(' ')[0]}</b><span>{dateLabel(r.date||r.due||r.created_at).split(' ').slice(1).join(' ')}</span></div><div className="timeline-marker"/><div className="row-main"><span className="eyebrow">{r.type==='exam'?'EXAMEN':r.type==='attendance'?'ASISTENCIA':r.type==='assignment'?'ENTREGA':'ACTIVIDAD'}{r.name?` · ${r.name}`:''}</span><strong>{r.title||r.name||r.student_name||r.status||'Evento de clase'}</strong><span>{r.pending_reviews > 0 ? `${r.pending_reviews} por corregir` : r.body||r.description||r.feedback||'Consulta el detalle en tu clase.'}</span></div><ChevronRight size={17}/></Link>)}</div>:<Empty title={emptyTitle} detail=""/>}
function ReportTile({icon:Icon,title,value,detail}:{icon:typeof Users;title:string;value:unknown;detail:string}) {return <div className="report-tile"><span className="quick-icon"><Icon size={19}/></span><span className="stat-label">{title}</span><strong>{String(value)}</strong><small>{detail}</small></div>}
function PageHeader({kicker,title,subtitle}:{kicker:string;title:string;subtitle:string}) {return <div className="page-header"><span className="eyebrow">{kicker}</span><h1>{title}</h1><p className="muted">{subtitle}</p></div>}
function PanelHead({kicker,title,action}:{kicker:string;title:string;action?:React.ReactNode}) {return <div className="panel-head"><div><span className="eyebrow">{kicker}</span><h2>{title}</h2></div>{action}</div>}
function Empty({title,detail}:{title:string;detail:string}) {return <div className="empty-state"><div className="empty-icon"><Sparkles size={21}/></div><strong>{title}</strong>{detail&&<p>{detail}</p>}</div>}
function RowsSkeleton() {return <div className="rows-skeleton">{[1,2,3].map(i=><div key={i}><span className="skeleton circle"/><span className="skeleton line"/><span className="skeleton short"/></div>)}</div>}
function Brand() {return <span className="brand-mark">a.</span>}
function Field({label,...props}:{label:string;name:string;type?:string;required?:boolean;placeholder?:string;minLength?:number;maxLength?:number;value?:string;textarea?:boolean}) {const {textarea,value,...input}=props;return <label className="field"><span>{label}</span>{textarea?<textarea {...input} defaultValue={value} rows={4} placeholder={props.placeholder||label} required={props.required}/>:<Input {...input} defaultValue={value} type={props.type||'text'} className={props.type === 'checkbox' ? '!w-5 !h-5 accent-emerald-700' : undefined} placeholder={props.placeholder||label} required={props.required}/>}</label>}
type FormField=Parameters<typeof Field>[0];

function subjectColorField(value = defaultSubjectColor): FormField {
  return { name: 'subject_color', label: 'Color de la asignatura', type: 'color', value };
}
function openForm(title:string,fields:FormField[],save:(data:Row)=>Promise<string|void>):Promise<string|void>{return new Promise(resolve=>{const root=document.createElement('div');document.body.append(root);const cleanup=()=>{root.remove();};const Form=()=>{const [busy,setBusy]=useState(false);const [error,setError]=useState('');const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);const form=new FormData(e.currentTarget);const data:Row={};fields.forEach(f=>data[f.name]=form.get(f.name));try{const result=await save(data);cleanup();resolve(result);}catch(e){setError((e as Error).message);setBusy(false);}};return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget){cleanup();resolve();}}}><section className="modal-card"><button className="modal-close" onClick={()=>{cleanup();resolve();}}><X size={19}/></button><span className="eyebrow">APPCLASE</span><h2>{title}</h2><form onSubmit={submit} className="form-stack">{fields.map(f=><Field key={f.name} {...f}/>)}{error&&<div className="error-box">{error}</div>}<div className="modal-actions"><button type="button" className="button soft" onClick={()=>{cleanup();resolve();}}>Cancelar</button><button className="button primary" disabled={busy}>{busy?'Guardando…':'Guardar'} <ArrowRight size={16}/></button></div></form></section></div>};createRoot(root).render(<Form/>);});}
function openDetails(title:string,details:string):Promise<void>{return new Promise(resolve=>{const host=document.createElement('div');document.body.append(host);const root=createRoot(host);const close=()=>{root.unmount();host.remove();resolve();};const Details=()=>{const [copied,setCopied]=useState(false);const copy=async()=>{try{await navigator.clipboard.writeText(details);setCopied(true);}catch{setCopied(false);}};return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close();}}><section className="modal-card" role="dialog" aria-modal="true" aria-labelledby="details-heading"><button className="modal-close" aria-label="Cerrar" onClick={close}><X size={19}/></button><span className="eyebrow">GUARDA ESTOS DATOS</span><h2 id="details-heading">{title}</h2><p className="muted">Se muestran una sola vez. Compártelos de forma privada con el profesor.</p><pre className="details-text">{details}</pre><div className="modal-actions"><button className="button soft" onClick={()=>void copy()}>{copied?<Check size={16}/>:<ClipboardList size={16}/>} {copied?'Copiado':'Copiar datos'}</button><button className="button primary" onClick={close}>Listo <Check size={16}/></button></div></section></div>};root.render(<Details/>);});}
function NotFound(){return <div className="content-wrap"><Empty title="No encontramos esta página" detail="Vuelve al inicio para seguir explorando APPCLASE."/><Link className="button primary centered-button" to="/">Ir al inicio</Link></div>}
function pageTitle(path:string){if(path==='/')return 'Inicio';if(path.startsWith('/centros/'))return 'Centro educativo';if(path.startsWith('/clases/'))return 'Clase';return ({'/agenda':'Agenda','/alumnos':'Personas','/tareas':'Tareas','/calificaciones':'Calificaciones','/asistencia':'Asistencia','/avisos':'Avisos','/cuenta':'Mi cuenta'} as Record<string,string>)[path]||'APPCLASE';}
function greeting(){const hour=new Date().getHours();return hour<12?'Buenos días':hour<19?'Buenas tardes':'Buenas noches';}
function formatToday(){return new Intl.DateTimeFormat('es-ES',{weekday:'long',day:'numeric',month:'long'}).format(new Date()).toUpperCase();}
